-- Attachment staging is cell scoped; promotion creates immutable objects addressed by sha256.
CREATE TABLE "frank_domain"."object_manifest" ("object_id" uuid PRIMARY KEY NOT NULL,"cell_id" text NOT NULL,"bucket" text NOT NULL,"object_key" text NOT NULL,"sha256" text NOT NULL,"size_bytes" bigint NOT NULL,"media_type" text NOT NULL,"manifest" jsonb NOT NULL,"created_at" timestamptz NOT NULL,CONSTRAINT "object_manifest_sha_uidx" UNIQUE("cell_id","sha256"));--> statement-breakpoint
CREATE UNIQUE INDEX "object_manifest_id_cell_uidx" ON "frank_domain"."object_manifest"("object_id","cell_id");--> statement-breakpoint
CREATE TABLE "frank_domain"."attachment" ("id" uuid PRIMARY KEY NOT NULL,"cell_id" text NOT NULL,"conversation_id" uuid,"turn_id" uuid,"upload_id" text NOT NULL,"object_id" uuid,"created_at" timestamptz NOT NULL,CONSTRAINT "attachment_upload_uidx" UNIQUE("cell_id","upload_id"),CONSTRAINT "attachment_conversation_cell_fk" FOREIGN KEY("conversation_id","cell_id") REFERENCES "frank_domain"."conversation"("id","cell_id") ON DELETE RESTRICT,CONSTRAINT "attachment_turn_cell_fk" FOREIGN KEY("turn_id","cell_id") REFERENCES "frank_domain"."chat_turn"("id","cell_id") ON DELETE RESTRICT,CONSTRAINT "attachment_object_cell_fk" FOREIGN KEY("object_id","cell_id") REFERENCES "frank_domain"."object_manifest"("object_id","cell_id") ON DELETE RESTRICT);--> statement-breakpoint
